const incoming = $input.first().json;
const raw = incoming && typeof incoming === 'object' && Object.hasOwn(incoming, 'body') ? incoming.body : incoming;
const body = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
const errors = [];
const orderId = typeof body.orderId === 'string' ? body.orderId.trim() : '';
const customerEmail = typeof body.customerEmail === 'string' ? body.customerEmail.trim() : '';
const quantity = body.quantity;
if (!orderId) errors.push('orderId is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail)) errors.push('customerEmail must be valid');
if (!Number.isInteger(quantity) || quantity <= 0 || quantity > 100000) errors.push('quantity must be a positive integer no greater than 100000');
if (errors.length) {
  return [{ json: { ok: false, statusCode: 400, errors } }];
}
return [{ json: { ok: true, statusCode: 200, order: { orderId, customerEmail, quantity } } }];
